public Page<InspectionStandard> searchStandards(String keyword, Pageable pageable) {
    BooleanBuilder builder = new BooleanBuilder();

    if (keyword != null && !keyword.trim().isEmpty()) {
        builder.or(inspectionStandard.content.containsIgnoreCase(keyword))
                .or(inspectionStandard.category.stringValue().containsIgnoreCase(keyword));
    }

    JPQLQuery<InspectionStandard> query = queryFactory
            .selectDistinct(inspectionStandard)
            .from(inspectionStandard)
            .leftJoin(inspectionStandardImage)
            .on(inspectionStandardImage.inspectionStandard.id.eq(inspectionStandard.id))
            .where(builder);

    // 정렬 적용
    if (pageable.getSort().isSorted()) {
        pageable.getSort().forEach(order -> {
            if (order.getProperty().equals("id")) {
                if (order.isAscending()) {
                    query.orderBy(inspectionStandard.id.asc());
                } else {
                    query.orderBy(inspectionStandard.id.desc());
                }
            } else if (order.getProperty().equals("createdDate")) {
                if (order.isAscending()) {
                    query.orderBy(inspectionStandard.createdDate.asc());
                } else {
                    query.orderBy(inspectionStandard.createdDate.desc());
                }
            } else if (order.getProperty().equals("modifiedDate")) {
                if (order.isAscending()) {
                    query.orderBy(inspectionStandard.modifiedDate.asc());
                } else {
                    query.orderBy(inspectionStandard.modifiedDate.desc());
                }
            }
        });
    } else {
        // 기본 정렬: ID 기준 내림차순
        query.orderBy(inspectionStandard.id.desc());
    }

    // 페이징 적용
    long total = query.fetchCount();
    List<InspectionStandard> results = query
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize())
            .fetch();

    return new PageImpl<>(results, pageable, total);
}

/**
 * 카테고리 및 키워드로 검수 기준 검색
 */
public Page<InquirySearchResultDto> searchInquiries(InquirySearchCondition condition, Pageable pageable) {
    QInquiry inquiry = QInquiry.inquiry;
    QUser user = QUser.user;

    // 검색 조건 빌더
    BooleanBuilder builder = new BooleanBuilder();

    // 카테고리 조건
    if (condition.getCategory() != null) {
        builder.and(inquiry.category.eq(condition.getCategory()));
    }

    // 상태 조건
    if (condition.getStatus() != null) {
        builder.and(inquiry.status.eq(condition.getStatus()));
    }

    // 사용자 ID 조건
    if (condition.getUserId() != null) {
        builder.and(inquiry.user.id.eq(condition.getUserId()));
    }

    // 키워드 검색 (제목 또는 내용)
    if (StringUtils.hasText(condition.getKeyword())) {
        builder.and(
                inquiry.title.containsIgnoreCase(condition.getKeyword())
                        .or(inquiry.content.containsIgnoreCase(condition.getKeyword()))
        );
    }

    // 날짜 범위 검색
    if (condition.getStartDate() != null) {
        builder.and(inquiry.createdDate.goe(condition.getStartDate()));
    }

    if (condition.getEndDate() != null) {
        LocalDateTime endOfDay = condition.getEndDate().plusDays(1).minusNanos(1);
        builder.and(inquiry.createdDate.loe(endOfDay));
    }

    // 비공개 문의 필터링 (관리자가 아닌 경우)
    if (!condition.isAdmin()) {
        builder.and(inquiry.isPrivate.eq(false).or(inquiry.user.id.eq(condition.getUserId())));
    }

    // 쿼리 실행: 결과 카운트 조회
    Long total = queryFactory
            .select(inquiry.count())
            .from(inquiry)
            .leftJoin(inquiry.user, user)
            .where(builder)
            .fetchOne();

    // 결과가 없는 경우 빈 페이지 반환
    if (total == null || total == 0) {
        return new PageImpl<>(List.of(), pageable, 0);
    }

    // 쿼리 실행: 결과 데이터 조회
    List<InquirySearchResultDto> content = queryFactory
            .select(Projections.constructor(
                    InquirySearchResultDto.class,
                    inquiry.id,
                    inquiry.title,
                    inquiry.content,
                    inquiry.answer,
                    inquiry.status,
                    inquiry.category,
                    inquiry.isPrivate,
                    inquiry.createdDate,
                    inquiry.modifiedDate,
                    user.id.as("userId"),
                    user.email,
                    user.profile.profileName,
                    user.profile.Name
            ))
            .from(inquiry)
            .leftJoin(inquiry.user, user)
            .leftJoin(user.profile)
            .where(builder)
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize())
            .orderBy(inquiry.createdDate.desc())
            .fetch();

    return new PageImpl<>(content, pageable, total);
}

